import requests

def get_user_message_count(channel):
    response = requests.get(f"https://slack.com/api/conversations.history?channel={channel}&limit=1000")
    data = response.json()
    user_message_count = {}
    for message in data['messages']:
        user = message['user']
        if user in user_message_count:
            user_message_count[user] += 1
        else:
            user_message_count[user] = 1
    return user_message_count

def sort_users_by_message_count(user_message_count):
    sorted_users = sorted(user_message_count.items(), key=lambda x: (-x[1], x[0]))
    return sorted_users

def send_congratulatory_message(sorted_users):
    for i, (user, count) in enumerate(sorted_users):
        print(f"Congrats on being the {i+1}-th most active user!")

channels = ["general", "random", "private", "External_0"]
user_message_count = {}
for channel in channels:
    channel_user_message_count = get_user_message_count(channel)
    for user, count in channel_user_message_count.items():
        if user in user_message_count:
            user_message_count[user] += count
        else:
            user_message_count[user] = count

sorted_users = sort_users_by_message_count(user_message_count)
send_congratulatory_message(sorted_users)
